head.script:
scwin.trigger1_onclick = function(e) {
    gridView1.setDisabled(true);
    //alert(gridView1.getDisabled());
};
scwin.trigger2_onclick = function(e) {
    gridView1.setDisabled(false);
    //alert(gridView1.getDisabled());
};
scwin.checkVal = function() {
    return gridView1.setDisabled(true);
}
scwin.unitTest = function() {
    //init
    // WebSquare.wUnit.start();
    //Test step 0. gridview속성에 disabledScrollHidden="true"속성을 추가한다.
    //0. Add the disabledScrollHidden = "true" attribute to the gridview property.
    //Verify step 0. The disabledScrollHidden = "true" attribute is added.
    //Test step 1. 샘플파일 실행 후 "gridView Disable"버튼을 클릭한다.
    //1. After running the sample file, click the "gridView Disable" button.
    //Verify step 1. The vertical scroll bar is hidden.
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("set", "scwin.checkVal()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#gridView1_scrollY_div').css('overflow') == 'hidden'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 2. 'gridView Enable'버튼을 클릭한다.
    //2. Click the 'gridView Enable' button.
    //Verify step 2. The vertical scroll bar is displayed (previously no function)
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger2').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#gridView1_scrollY_div').css('overflow-y') == 'scroll'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    dataList1.insertRow();
    dataList1.insertRow();
    dataList1.insertRow();
    dataList1.insertRow();
    dataList1.insertRow();
    dataList1.insertRow();
    dataList1.insertRow();
    dataList1.insertRow();
    dataList1.insertRow();
    dataList1.insertRow();
    dataList1.insertRow();
    dataList1.insertRow();
    dataList1.insertRow();
    dataList1.insertRow();
    dataList1.insertRow();
    setTimeout(function() {
        //
        gridView1.setFocusedCell(0, 0);
    }, 100);
    gridView1.setSize("height", 138);
    //scwin.test = function(){
    //    ngmf.layerAlert("onscrollend[" + this.id + "]");
    // gridView1.setOverflowYHidden();
    //    console.log(111);
    //}
    //Function 
    //Created by: Thuyet.Pham
    //Created date: 26-Feb-2018
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
